                    let context_menu_event_cls = activation.avm2().classes().contextmenuevent;
                    let menu_select_string = istr!("menuSelect");
                    let menu_evt = Avm2EventObject::from_class_and_args(
                        &mut activation,
                        context_menu_event_cls,
                        &[
                            menu_select_string.into(),
                            false.into(),
                            false.into(),
                            hit_obj.into(),
                            hit_obj.into(),
