        PhysicalKey::Escape => KeyCode::ESCAPE,
        PhysicalKey::F1 => KeyCode::F1,
        PhysicalKey::F2 => KeyCode::F2,
        PhysicalKey::F3 => KeyCode::F3,
        PhysicalKey::F4 => KeyCode::F4,
        PhysicalKey::F5 => KeyCode::F5,
        PhysicalKey::F6 => KeyCode::F6,
        PhysicalKey::F7 => KeyCode::F7,
        PhysicalKey::F8 => KeyCode::F8,
        PhysicalKey::F9 => KeyCode::F9,
        PhysicalKey::F10 => KeyCode::F10,
        PhysicalKey::F11 => KeyCode::F11,
        PhysicalKey::F12 => KeyCode::F12,
        PhysicalKey::F13 => KeyCode::F13,
        PhysicalKey::F14 => KeyCode::F14,
        PhysicalKey::F15 => KeyCode::F15,
        PhysicalKey::F16 => KeyCode::F16,
        PhysicalKey::F17 => KeyCode::F17,
        PhysicalKey::F18 => KeyCode::F18,
        PhysicalKey::F19 => KeyCode::F19,
        PhysicalKey::F20 => KeyCode::F20,
        PhysicalKey::F21 => KeyCode::F21,
        PhysicalKey::F22 => KeyCode::F22,
        PhysicalKey::F23 => KeyCode::F23,
        PhysicalKey::F24 => KeyCode::F24,
        PhysicalKey::Fn => return None,
        PhysicalKey::FnLock => return None,
        // TODO FP returns -1 for PrintScreen?
        PhysicalKey::PrintScreen => KeyCode::UNKNOWN,
        PhysicalKey::ScrollLock => KeyCode::SCROLL_LOCK,
        PhysicalKey::Pause => KeyCode::PAUSE,
        _ => return None,
    })
}

fn map_to_key_code_logical(key: LogicalKey, location: KeyLocation) -> Option<KeyCode> {
    let is_numpad = matches!(location, KeyLocation::Numpad);
    Some(match key {
        LogicalKey::Named(NamedKey::Backspace) => KeyCode::BACKSPACE,
        LogicalKey::Named(NamedKey::Tab) => KeyCode::TAB,
        LogicalKey::Named(NamedKey::Enter) => KeyCode::ENTER,
        LogicalKey::Named(NamedKey::Shift) => KeyCode::SHIFT,
        LogicalKey::Named(NamedKey::Control) => KeyCode::CONTROL,
        LogicalKey::Named(NamedKey::Alt) => KeyCode::ALT,
        LogicalKey::Named(NamedKey::AltGraph) => return None,
        LogicalKey::Named(NamedKey::ContextMenu) => return None,
        LogicalKey::Named(NamedKey::CapsLock) => KeyCode::CAPS_LOCK,
        LogicalKey::Named(NamedKey::Escape) => KeyCode::ESCAPE,
        LogicalKey::Character(' ') => KeyCode::SPACE,
        LogicalKey::Character('0') if is_numpad => KeyCode::NUMPAD_0,
        LogicalKey::Character('1') if is_numpad => KeyCode::NUMPAD_1,
        LogicalKey::Character('2') if is_numpad => KeyCode::NUMPAD_2,
        LogicalKey::Character('3') if is_numpad => KeyCode::NUMPAD_3,
        LogicalKey::Character('4') if is_numpad => KeyCode::NUMPAD_4,
        LogicalKey::Character('5') if is_numpad => KeyCode::NUMPAD_5,
        LogicalKey::Character('6') if is_numpad => KeyCode::NUMPAD_6,
        LogicalKey::Character('7') if is_numpad => KeyCode::NUMPAD_7,
        LogicalKey::Character('8') if is_numpad => KeyCode::NUMPAD_8,
        LogicalKey::Character('9') if is_numpad => KeyCode::NUMPAD_9,
        LogicalKey::Character('*') if is_numpad => KeyCode::NUMPAD_MULTIPLY,
        LogicalKey::Character('+') if is_numpad => KeyCode::NUMPAD_ADD,
        LogicalKey::Character('-') if is_numpad => KeyCode::NUMPAD_SUBTRACT,
        LogicalKey::Character('.' | ',') if is_numpad => KeyCode::NUMPAD_DECIMAL,
        LogicalKey::Character('/') if is_numpad => KeyCode::NUMPAD_DIVIDE,
        LogicalKey::Character('0' | ')') => KeyCode::NUMBER_0,
        LogicalKey::Character('1' | '!') => KeyCode::NUMBER_1,
        LogicalKey::Character('2' | '@') => KeyCode::NUMBER_2,
        LogicalKey::Character('3' | '#') => KeyCode::NUMBER_3,
        LogicalKey::Character('4' | '$') => KeyCode::NUMBER_4,
        LogicalKey::Character('5' | '%') => KeyCode::NUMBER_5,
        LogicalKey::Character('6' | '^') => KeyCode::NUMBER_6,
        LogicalKey::Character('7' | '&') => KeyCode::NUMBER_7,
        LogicalKey::Character('8' | '*') => KeyCode::NUMBER_8,
        LogicalKey::Character('9' | '(') => KeyCode::NUMBER_9,
        LogicalKey::Character(';' | ':') => KeyCode::SEMICOLON,
        LogicalKey::Character('=' | '+') => KeyCode::EQUAL,
        LogicalKey::Character(',' | '<') => KeyCode::COMMA,
        LogicalKey::Character('-' | '_') => KeyCode::MINUS,
        LogicalKey::Character('.' | '>') => KeyCode::PERIOD,
        LogicalKey::Character('/' | '?') => KeyCode::SLASH,
        LogicalKey::Character('`' | '~') => KeyCode::BACKQUOTE,
        LogicalKey::Character('[' | '{') => KeyCode::LEFTBRACKET,
        LogicalKey::Character('\\' | '|') => KeyCode::BACKSLASH,
        LogicalKey::Character(']' | '}') => KeyCode::RIGHTBRACKET,
        LogicalKey::Character('\'' | '"') => KeyCode::QUOTE,
        LogicalKey::Named(NamedKey::PageUp) => KeyCode::PAGE_UP,
        LogicalKey::Named(NamedKey::PageDown) => KeyCode::PAGE_DOWN,
        LogicalKey::Named(NamedKey::End) => KeyCode::END,
        LogicalKey::Named(NamedKey::Home) => KeyCode::HOME,
        LogicalKey::Named(NamedKey::ArrowLeft) => KeyCode::LEFT,
        LogicalKey::Named(NamedKey::ArrowUp) => KeyCode::UP,
        LogicalKey::Named(NamedKey::ArrowRight) => KeyCode::RIGHT,
        LogicalKey::Named(NamedKey::ArrowDown) => KeyCode::DOWN,
        LogicalKey::Named(NamedKey::Insert) => KeyCode::INSERT,
        LogicalKey::Named(NamedKey::Delete) => KeyCode::DELETE,
        LogicalKey::Named(NamedKey::Pause) => KeyCode::PAUSE,
        LogicalKey::Named(NamedKey::NumLock) => KeyCode::NUM_LOCK,
        LogicalKey::Named(NamedKey::ScrollLock) => KeyCode::SCROLL_LOCK,
        LogicalKey::Named(NamedKey::F1) => KeyCode::F1,
        LogicalKey::Named(NamedKey::F2) => KeyCode::F2,
        LogicalKey::Named(NamedKey::F3) => KeyCode::F3,
        LogicalKey::Named(NamedKey::F4) => KeyCode::F4,
        LogicalKey::Named(NamedKey::F5) => KeyCode::F5,
        LogicalKey::Named(NamedKey::F6) => KeyCode::F6,
        LogicalKey::Named(NamedKey::F7) => KeyCode::F7,
        LogicalKey::Named(NamedKey::F8) => KeyCode::F8,
        LogicalKey::Named(NamedKey::F9) => KeyCode::F9,
        LogicalKey::Named(NamedKey::F10) => KeyCode::F10,
        LogicalKey::Named(NamedKey::F11) => KeyCode::F11,
        LogicalKey::Named(NamedKey::F12) => KeyCode::F12,
        LogicalKey::Named(NamedKey::F13) => KeyCode::F13,
        LogicalKey::Named(NamedKey::F14) => KeyCode::F14,
        LogicalKey::Named(NamedKey::F15) => KeyCode::F15,
        LogicalKey::Named(NamedKey::F16) => KeyCode::F16,
        LogicalKey::Named(NamedKey::F17) => KeyCode::F17,
        LogicalKey::Named(NamedKey::F18) => KeyCode::F18,
        LogicalKey::Named(NamedKey::F19) => KeyCode::F19,
        LogicalKey::Named(NamedKey::F20) => KeyCode::F20,
        LogicalKey::Named(NamedKey::F21) => KeyCode::F21,
        LogicalKey::Named(NamedKey::F22) => KeyCode::F22,
        LogicalKey::Named(NamedKey::F23) => KeyCode::F23,
        LogicalKey::Named(NamedKey::F24) => KeyCode::F24,
        LogicalKey::Character(char) => {
            // Handle alphabetic characters
            map_character_to_key_code(char).unwrap_or(KeyCode::UNKNOWN)
        }
        _ => return None,
    })
}

fn map_character_to_key_code(char: char) -> Option<KeyCode> {
    if char.is_ascii_alphabetic() {
        // ASCII alphabetic characters are all mapped to
        // their respective KeyCodes, which happen to have
        // the same numerical value as uppercase characters.
        return Some(KeyCode::from_code(char.to_ascii_uppercase() as u32));
    }

    if !char.is_ascii() {
        // Non-ASCII inputs have codes equal to their Unicode codes and yes,
        // they overlap with other codes, so that typing '½' and '-' both produce 189.
        return Some(KeyCode::from_code(char as u32));
    }

    None
}

#[cfg(test)]
mod tests {
    use super::*;

    fn key(char: char, physical: PhysicalKey) -> KeyDescriptor {
        KeyDescriptor {
            logical_key: LogicalKey::Character(char),
            physical_key: physical,
            key_location: KeyLocation::Standard,
        }
    }

    #[test]
    fn spurious_key_up_ignored() {
        let mut input = InputManager::new(HashMap::new());

        // Spurious KeyUp for 'a' - no preceding KeyDown
        assert!(
            input
                .process_event(PlayerEvent::KeyUp {
                    key: key('a', PhysicalKey::KeyA)
                })
                .is_none()
        );

        // Normal KeyDown 'w'
        assert!(
            input
                .process_event(PlayerEvent::KeyDown {
                    key: key('w', PhysicalKey::KeyW)
                })
                .is_some()
        );

        // Spurious KeyUp for 'b' - different key, never pressed
        assert!(
            input
                .process_event(PlayerEvent::KeyUp {
                    key: key('b', PhysicalKey::KeyB)
                })
                .is_none()
        );

        // Valid KeyUp for 'w'
        assert!(
            input
                .process_event(PlayerEvent::KeyUp {
                    key: key('w', PhysicalKey::KeyW)
                })
                .is_some()
        );

        // Duplicate KeyUp for 'w' - already released
        assert!(
            input
                .process_event(PlayerEvent::KeyUp {
                    key: key('w', PhysicalKey::KeyW)
                })
                .is_none()
        );
    }
}

use crate::avm2::Error;
use crate::avm2::activation::Activation;
use crate::avm2::function::FunctionArgs;
use crate::avm2::globals::slots::flash_events_mouse_event as slots;
use crate::avm2::object::{Object, TObject as _};
use crate::avm2::value::Value;
use crate::display_object::TDisplayObject;
use swf::Point;

/// Implements `stageX`'s getter.
pub fn get_stage_x<'gc>(
    activation: &mut Activation<'_, 'gc>,
    this: Value<'gc>,
    _args: FunctionArgs<'_, 'gc>,
) -> Result<Value<'gc>, Error<'gc>> {
    let this = this.as_object().unwrap();

    local_to_stage_x(activation, this, slots::_LOCAL_X, slots::_LOCAL_Y)
}

/// Implements `stageY`'s getter.
pub fn get_stage_y<'gc>(
    activation: &mut Activation<'_, 'gc>,
    this: Value<'gc>,
    _args: FunctionArgs<'_, 'gc>,
) -> Result<Value<'gc>, Error<'gc>> {
    let this = this.as_object().unwrap();

    local_to_stage_y(activation, this, slots::_LOCAL_X, slots::_LOCAL_Y)
}

pub fn update_after_event<'gc>(
    activation: &mut Activation<'_, 'gc>,
    _this: Value<'gc>,
    _args: FunctionArgs<'_, 'gc>,
) -> Result<Value<'gc>, Error<'gc>> {
    *activation.context.needs_render = true;
    Ok(Value::Undefined)
}

pub(super) fn local_to_stage_x<'gc>(
    activation: &mut Activation<'_, 'gc>,
    this: Object<'gc>,
    slot_x: usize,
    slot_y: usize,
) -> Result<Value<'gc>, Error<'gc>> {
    if let Some(evt) = this.as_event() {
        let local_x = this.get_slot(slot_x).coerce_to_number(activation)?;
        let local_y = this.get_slot(slot_y).coerce_to_number(activation)?;

        if local_x.is_nan() || local_y.is_nan() {
            return Ok(Value::Number(local_x));
        } else if let Some(target) = evt.target().and_then(|t| t.as_display_object()) {
            let local = Point::from_pixels(local_x, local_y);
            // `local_to_global` does a matrix multiplication, which in general
            // depends on both the x and y coordinates.
            let global = target.local_to_global(local);
            return Ok(Value::Number(global.x.to_pixels()));
        } else {
            return Ok(Value::Number(local_x * 0.0));
        }
    }

    Ok(Value::Undefined)
}

pub(super) fn local_to_stage_y<'gc>(
    activation: &mut Activation<'_, 'gc>,
    this: Object<'gc>,
    slot_x: usize,
    slot_y: usize,
) -> Result<Value<'gc>, Error<'gc>> {
    if let Some(evt) = this.as_event() {
        let local_x = this.get_slot(slot_x).coerce_to_number(activation)?;
        let local_y = this.get_slot(slot_y).coerce_to_number(activation)?;

        if local_x.is_nan() || local_y.is_nan() {
            return Ok(Value::Number(local_y));
        } else if let Some(target) = evt.target().and_then(|t| t.as_display_object()) {
            let local = Point::from_pixels(local_x, local_y);
            // `local_to_global` does a matrix multiplication, which in general
            // depends on both the x and y coordinates.
            let global = target.local_to_global(local);
            return Ok(Value::Number(global.y.to_pixels()));
        } else {
            return Ok(Value::Number(local_y * 0.0));
        }
    }

    Ok(Value::Undefined)
}

//! Object representation for events

use crate::avm2::Error;
use crate::avm2::activation::Activation;
use crate::avm2::events::Event;
use crate::avm2::object::script_object::ScriptObjectData;
use crate::avm2::object::{ClassObject, Object, ScriptObject, TObject};
use crate::avm2::value::Value;
use crate::context::UpdateContext;
use crate::display_object::TDisplayObject;
use crate::display_object::{DisplayObject, InteractiveObject, TInteractiveObject};
use crate::events::{KeyCode, MouseButton};
use crate::string::AvmString;
use gc_arena::barrier::unlock;
use gc_arena::{Collect, Gc, GcWeak, Mutation, lock::RefLock};
use ruffle_common::utils::HasPrefixField;
use ruffle_macros::istr;
use std::cell::{Ref, RefMut};
use std::fmt::Debug;

/// A class instance allocator that allocates Event objects.
pub fn event_allocator<'gc>(
    class: ClassObject<'gc>,
    activation: &mut Activation<'_, 'gc>,
) -> Result<Object<'gc>, Error<'gc>> {
    let base = ScriptObjectData::new(class);

    Ok(EventObject(Gc::new(
        activation.gc(),
        EventObjectData {
            base,
            event: RefLock::new(Event::new(istr!(""))),
        },
    ))
    .into())
}

#[derive(Clone, Collect, Copy)]
#[collect(no_drop)]
pub struct EventObject<'gc>(pub Gc<'gc, EventObjectData<'gc>>);

#[derive(Clone, Collect, Copy, Debug)]
#[collect(no_drop)]
pub struct EventObjectWeak<'gc>(pub GcWeak<'gc, EventObjectData<'gc>>);

#[derive(Clone, Collect, HasPrefixField)]
#[collect(no_drop)]
#[repr(C, align(8))]
pub struct EventObjectData<'gc> {
    /// Base script object
    base: ScriptObjectData<'gc>,

    /// The event this object holds.
    event: RefLock<Event<'gc>>,
}

impl<'gc> EventObject<'gc> {
    /// Create a bare Event instance while skipping the usual `construct()` pipeline.
    /// It's just slightly faster and doesn't require an Activation.
    /// This is equivalent to
    /// classes.event.construct(activation, &[event_type, false, false])
    pub fn bare_default_event(
        context: &mut UpdateContext<'gc>,
        event_type: &str,
    ) -> EventObject<'gc> {
        Self::bare_event(context, event_type, false, false)
    }

    /// Create a bare Event instance while skipping the usual `construct()` pipeline.
    /// It's just slightly faster and doesn't require an Activation.
    /// Note that if you need an Event subclass, you need to construct it via .construct().
    pub fn bare_event(
        context: &mut UpdateContext<'gc>,
        event_type: &str,
        bubbles: bool,
        cancelable: bool,
    ) -> EventObject<'gc> {
        let class = context.avm2.classes().event;
        let base = ScriptObjectData::new(class);

        let event_type = AvmString::new_utf8(context.gc(), event_type);

        let mut event = Event::new(event_type);
        event.set_bubbles(bubbles);
        event.set_cancelable(cancelable);

        EventObject(Gc::new(
            context.gc(),
            EventObjectData {
                base,
                event: RefLock::new(event),
            },
        ))
    }

    #[inline]
    pub fn from_class_and_args(
        activation: &mut Activation<'_, 'gc>,
        class: ClassObject<'gc>,
        args: &[Value<'gc>],
    ) -> EventObject<'gc> {
        // We don't expect Event classes to error in their constructors or to
        // return anything other than an EventObject
        class
            .construct(activation, args)
            .unwrap()
            .as_object()
            .unwrap()
            .as_event_object()
            .unwrap()
    }

    pub fn mouse_event(
        activation: &mut Activation<'_, 'gc>,
        event_type: AvmString<'gc>,
        target: DisplayObject<'gc>,
        related_object: Option<InteractiveObject<'gc>>,
        delta: i32,
        bubbles: bool,
        button: MouseButton,
    ) -> EventObject<'gc> {
        let local = target.local_mouse_position(activation.context);

        let mouse_event_cls = activation.avm2().classes().mouseevent;
        Self::from_class_and_args(
            activation,
            mouse_event_cls,
            &[
                event_type.into(),
                // bubbles
                bubbles.into(),
                // cancellable
                false.into(),
                // localX
                local.x.to_pixels().into(),
                // localY
                local.y.to_pixels().into(),
                // relatedObject
                related_object
                    .map(|o| o.as_displayobject().object2_or_null())
                    .unwrap_or(Value::Null),
                // ctrlKey
                activation
                    .context
                    .input
                    .is_key_down(KeyCode::CONTROL)
                    .into(),
                // altKey
                activation.context.input.is_key_down(KeyCode::ALT).into(),
                // shiftKey
                activation.context.input.is_key_down(KeyCode::SHIFT).into(),
                // buttonDown
                activation.context.input.is_key_down(button.into()).into(),
                // delta
                delta.into(),
            ],
        )
    }

    pub fn mouse_event_down(
        activation: &mut Activation<'_, 'gc>,
        target: DisplayObject<'gc>,
        button: MouseButton,
    ) -> EventObject<'gc> {
        let event_name = match button {
            MouseButton::Left => istr!("mouseDown"),
            MouseButton::Right => istr!("rightMouseDown"),
            MouseButton::Middle => istr!("middleMouseDown"),
            MouseButton::Unknown => unreachable!(),
        };

        Self::mouse_event(activation, event_name, target, None, 0, true, button)
    }

    pub fn mouse_event_up(
        activation: &mut Activation<'_, 'gc>,
        target: DisplayObject<'gc>,
        button: MouseButton,
    ) -> EventObject<'gc> {
        let event_name = match button {
            MouseButton::Left => istr!("mouseUp"),
            MouseButton::Right => istr!("rightMouseUp"),
            MouseButton::Middle => istr!("middleMouseUp"),
            MouseButton::Unknown => unreachable!(),
        };

        Self::mouse_event(activation, event_name, target, None, 0, true, button)
    }

    pub fn mouse_event_click(
        activation: &mut Activation<'_, 'gc>,
        target: DisplayObject<'gc>,
        button: MouseButton,
    ) -> EventObject<'gc> {
        let event_name = match button {
            MouseButton::Left => istr!("click"),
            MouseButton::Right => istr!("rightClick"),
            MouseButton::Middle => istr!("middleClick"),
            MouseButton::Unknown => unreachable!(),
        };

        Self::mouse_event(activation, event_name, target, None, 0, true, button)
    }

    pub fn text_event(
        activation: &mut Activation<'_, 'gc>,
        event_type: &str,
        text: AvmString<'gc>,
        bubbles: bool,
        cancelable: bool,
    ) -> EventObject<'gc> {
        let event_type = AvmString::new_utf8(activation.gc(), event_type);

        let text_event_cls = activation.avm2().classes().textevent;
        Self::from_class_and_args(
            activation,
            text_event_cls,
            &[
                event_type.into(),
                // bubbles
                bubbles.into(),
                // cancelable
                cancelable.into(),
                // text
                text.into(),
            ],
        )
    }

    pub fn net_status_event<'a>(
        activation: &mut Activation<'_, 'gc>,
        info: impl IntoIterator<Item = (&'a str, &'a str)>,
    ) -> EventObject<'gc> {
        let info_object = ScriptObject::new_object(activation.context);
        for (key, value) in info {
            let key = AvmString::new_utf8(activation.gc(), key);
            let value = AvmString::new_utf8(activation.gc(), value);

            info_object.set_dynamic_property(key, Value::String(value), activation.gc());
        }

        let event_name = istr!("netStatus");
        let net_status_cls = activation.avm2().classes().netstatusevent;
        Self::from_class_and_args(
            activation,
            net_status_cls,
            &[
                event_name.into(),
                //bubbles
                false.into(),
                //cancelable
                false.into(),
                info_object.into(),
            ],
        )
    }

    pub fn progress_event(
        activation: &mut Activation<'_, 'gc>,
        event_type: &str,
        bytes_loaded: usize,
        bytes_total: usize,
    ) -> EventObject<'gc> {
        let event_type = AvmString::new_utf8(activation.gc(), event_type);

        let progress_event_cls = activation.avm2().classes().progressevent;
        Self::from_class_and_args(
            activation,
            progress_event_cls,
            &[
                event_type.into(),
                // bubbles
                false.into(),
                // cancelable
                false.into(),
                // bytesLoaded
                (bytes_loaded as f64).into(),
                // bytesTotal
                (bytes_total as f64).into(),
            ],
        )
    }

    pub fn focus_event(
        activation: &mut Activation<'_, 'gc>,
        event_type: &str,
        cancelable: bool,
        related_object: Option<InteractiveObject<'gc>>,
        key_code: u32,
    ) -> EventObject<'gc> {
        let event_type = AvmString::new_utf8(activation.gc(), event_type);
        let shift_key = activation.context.input.is_key_down(KeyCode::SHIFT);

        let none_string = istr!("none");

        let focus_event_cls = activation.avm2().classes().focusevent;
        Self::from_class_and_args(
            activation,
            focus_event_cls,
            &[
                event_type.into(),
                true.into(),
                cancelable.into(),
                related_object
                    .map(|o| o.as_displayobject().object2_or_null())
                    .unwrap_or(Value::Null),
                shift_key.into(),
                key_code.into(),
                none_string.into(), // TODO implement direction
            ],
        )
    }

    pub fn io_error_event(
        activation: &mut Activation<'_, 'gc>,
        error_msg: &str,
        error_code: u32,
    ) -> EventObject<'gc> {
        let event_name = istr!("ioError");
        let error_msg = AvmString::new_utf8(activation.gc(), error_msg);
        let io_error_event_cls = activation.avm2().classes().ioerrorevent;
        Self::from_class_and_args(
            activation,
            io_error_event_cls,
            &[
                event_name.into(),
                false.into(),
                false.into(),
                error_msg.into(),
                error_code.into(),
            ],
        )
    }

    pub fn http_status_event(
        activation: &mut Activation<'_, 'gc>,
        status: u16,
        redirected: bool,
    ) -> EventObject<'gc> {
        let event_name = istr!("httpStatus");
        let http_status_event_cls = activation.avm2().classes().httpstatusevent;
        Self::from_class_and_args(
            activation,
            http_status_event_cls,
            &[
                event_name.into(),
                false.into(),
                false.into(),
                status.into(),
                redirected.into(),
            ],
        )
    }

    pub fn event(self) -> Ref<'gc, Event<'gc>> {
        Gc::as_ref(self.0).event.borrow()
    }

    pub fn event_mut(self, mc: &Mutation<'gc>) -> RefMut<'gc, Event<'gc>> {
        unlock!(Gc::write(mc, self.0), EventObjectData, event).borrow_mut()
    }
}

impl<'gc> TObject<'gc> for EventObject<'gc> {
    fn gc_base(&self) -> Gc<'gc, ScriptObjectData<'gc>> {
        HasPrefixField::as_prefix_gc(self.0)
    }
}

impl Debug for EventObject<'_> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> Result<(), std::fmt::Error> {
        f.debug_struct("EventObject")
            .field("type", &self.0.event.borrow().event_type())
            .field("class", &self.base().class_name())
            .field("ptr", &Gc::as_ptr(self.0))
            .finish()
    }
}

