    ///
    /// # Examples
    ///
    /// ```rust
    /// assert_eq!(swf::Twips::ONE_PX.to_pixels(), 1.0);
    /// ```
    pub const ONE_PX: Self = Self(Self::TWIPS_PER_PIXEL);

